"""Typed protobuf payload builders for Google Flights RPC requests.

Constructs the serialized protobuf payloads used in the ?tfs= query parameter
and decodes ItinerarySummary responses. Uses string IATA codes directly
(no Airport enum dependency).
"""

import base64
from dataclasses import dataclass
from typing import List, Literal, Optional

# flights_pb2 is generated by protoc and excluded from pyright analysis
# (see [tool.pyright] in pyproject.toml). The companion flights_pb2.pyi
# stub re-introduces typing for the messages/enums this module reaches
# for, so a typo like PB.Passneger.ADULT is caught at type-check time
# instead of becoming a runtime AttributeError.
from . import flights_pb2 as PB
from ._pricing import _validate_routing, _validate_pricing

AIRLINE_ALLIANCES = ["SKYTEAM", "STAR_ALLIANCE", "ONEWORLD"]

CabinClass = Literal["economy", "premium-economy", "business", "first"]

# Cabin class mapping (matches Google Flights internal Seat enum values)
CABIN_CLASS_MAP: dict[CabinClass, int] = {
    "economy": 1,
    "premium-economy": 2,
    "business": 3,
    "first": 4,
}


class SearchLeg:
    """A search leg defining origin, destination, date, and optional filters.

    Each search has one leg (one-way) or two legs (roundtrip). This class
    builds the per-leg protobuf data used in the ``?tfs=`` query parameter.

    Args:
        date: Departure date (YYYY-MM-DD).
        from_airport: Origin IATA code.
        to_airport: Destination IATA code.
        max_stops: Maximum number of stops. None = any.
        airlines: Filter to these airline IATA codes.
        max_duration: Maximum flight duration in minutes.
        connecting_airports: Allowed connecting airports; nonstops remain eligible.
        exclude_connecting_airports: Excluded connecting airports.
        min_layover_duration: Minimum layover in minutes.
        max_layover_duration: Maximum layover in minutes.
    """

    __slots__ = (
        "date",
        "from_airport",
        "to_airport",
        "max_stops",
        "airlines",
        "max_duration",
        "connecting_airports",
        "exclude_connecting_airports",
        "min_layover_duration",
        "max_layover_duration",
    )

    def __init__(
        self,
        *,
        date: str,
        from_airport: str,
        to_airport: str,
        max_stops: Optional[int] = None,
        airlines: Optional[List[str]] = None,
        max_duration: Optional[int] = None,
        connecting_airports: Optional[list[str]] = None,
        exclude_connecting_airports: Optional[list[str]] = None,
        min_layover_duration: Optional[int] = None,
        max_layover_duration: Optional[int] = None,
    ):
        _validate_routing(
            max_duration,
            connecting_airports,
            exclude_connecting_airports,
            min_layover_duration,
            max_layover_duration,
        )
        self.max_duration = max_duration
        self.connecting_airports = connecting_airports
        self.exclude_connecting_airports = exclude_connecting_airports
        self.min_layover_duration = min_layover_duration
        self.max_layover_duration = max_layover_duration
        self.date = date
        self.from_airport = from_airport.upper()
        self.to_airport = to_airport.upper()
        self.max_stops = max_stops

        if airlines is not None:
            self.airlines = []
            for airline in airlines:
                airline = airline.upper()
                if not (len(airline) == 2 or airline in AIRLINE_ALLIANCES):
                    raise ValueError(
                        f"Invalid airline code: {airline}. "
                        f"Must be 2-char IATA code or alliance: {AIRLINE_ALLIANCES}"
                    )
                self.airlines.append(airline)
        else:
            self.airlines = None

    def apply_to(self, info) -> None:
        data = info.data.add()
        data.date = self.date
        data.from_flight.airport = self.from_airport
        data.to_flight.airport = self.to_airport
        if self.max_stops is not None:
            data.max_stops = self.max_stops
        if self.airlines is not None:
            data.airlines.extend(self.airlines)

        if self.max_duration is not None:
            data.max_duration = self.max_duration
        if self.connecting_airports:
            data.connecting_airports.extend(c.upper() for c in self.connecting_airports)
        if self.exclude_connecting_airports:
            data.exclude_connecting_airports.extend(
                c.upper() for c in self.exclude_connecting_airports
            )
        if self.min_layover_duration is not None:
            data.min_layover_duration = self.min_layover_duration
        if self.max_layover_duration is not None:
            data.max_layover_duration = self.max_layover_duration


class _PBPassengers:
    def __init__(
        self,
        *,
        adults: int = 1,
        children: int = 0,
        infants_in_seat: int = 0,
        infants_on_lap: int = 0,
    ):
        total = adults + children + infants_in_seat + infants_on_lap
        if total > 9:
            raise ValueError(f"Too many passengers ({total} > 9 max)")
        if infants_on_lap > adults:
            raise ValueError(
                f"Need at least one adult per infant on lap "
                f"({infants_on_lap} infants but only {adults} adults)"
            )

        self.pb = []
        self.pb += [PB.Passenger.ADULT for _ in range(adults)]
        self.pb += [PB.Passenger.CHILD for _ in range(children)]
        self.pb += [PB.Passenger.INFANT_IN_SEAT for _ in range(infants_in_seat)]
        self.pb += [PB.Passenger.INFANT_ON_LAP for _ in range(infants_on_lap)]

    def apply_to(self, info) -> None:
        for p in self.pb:
            info.passengers.append(p)


class TFSData:
    """Builds the ``?tfs=`` query parameter for Google Flights URL.

    TFS (Travel Flight Search) is the parameter name Google Flights uses
    in its URL to encode the serialized protobuf search request.
    """

    def __init__(
        self,
        *,
        flight_data: List[SearchLeg],
        seat: int,
        trip: int,
        passengers: _PBPassengers,
        max_stops: Optional[int] = None,
        exclude_basic_economy: bool = False,
        carry_on_bags: int = 0,
        checked_bags: int = 0,
        max_price: Optional[int] = None,
    ):
        _validate_pricing(carry_on_bags, checked_bags, max_price)
        self.carry_on_bags = carry_on_bags
        self.checked_bags = checked_bags
        self.max_price = max_price
        self.flight_data = flight_data
        self.seat = seat
        self.trip = trip
        self.passengers = passengers
        self.max_stops = max_stops
        self.exclude_basic_economy = exclude_basic_economy

    def pb(self):
        info = PB.Info()
        info.seat = self.seat
        info.trip = self.trip
        self.passengers.apply_to(info)

        for fd in self.flight_data:
            fd.apply_to(info)

        if self.max_stops is not None:
            for flight in info.data:
                flight.max_stops = self.max_stops

        if self.exclude_basic_economy:
            info.exclude_basic_economy = True

        if self.max_price is not None:
            info.max_price = self.max_price
        if self.carry_on_bags or self.checked_bags:
            info.baggage.carry_on_bags = self.carry_on_bags
            info.baggage.checked_bags = self.checked_bags

        return info

    def to_string(self) -> bytes:
        return self.pb().SerializeToString()

    def as_b64(self) -> bytes:
        return base64.b64encode(self.to_string())

    @staticmethod
    def from_interface(
        *,
        flight_data: List[SearchLeg],
        trip: Literal["round-trip", "one-way", "multi-city"],
        passengers: _PBPassengers,
        seat: Literal["economy", "premium-economy", "business", "first"],
        max_stops: Optional[int] = None,
        exclude_basic_economy: bool = False,
        carry_on_bags: int = 0,
        checked_bags: int = 0,
        max_price: Optional[int] = None,
    ) -> "TFSData":
        trip_t = {
            "round-trip": PB.Trip.ROUND_TRIP,
            "one-way": PB.Trip.ONE_WAY,
            "multi-city": PB.Trip.MULTI_CITY,
        }[trip]
        seat_t = {
            "economy": PB.Seat.ECONOMY,
            "premium-economy": PB.Seat.PREMIUM_ECONOMY,
            "business": PB.Seat.BUSINESS,
            "first": PB.Seat.FIRST,
        }[seat]
        return TFSData(
            flight_data=flight_data,
            seat=seat_t,
            trip=trip_t,
            passengers=passengers,
            max_stops=max_stops,
            exclude_basic_economy=exclude_basic_economy,
            carry_on_bags=carry_on_bags,
            checked_bags=checked_bags,
            max_price=max_price,
        )


@dataclass
class ItinerarySummary:
    """Decoded price data from a Google Flights itinerary summary token.

    The ``currency`` field is the 3-letter ISO 4217 code. The ``price``
    field stores the raw protobuf value — it is NOT used for display
    pricing. The authoritative price comes from ``Itinerary.direct_price``
    (the display integer at ``response[1][0][1]``).
    """

    flights: str
    price: float
    currency: str

    @classmethod
    def from_b64(cls, b64_string: str) -> "ItinerarySummary":
        try:
            raw = base64.b64decode(b64_string)
            pb = PB.ItinerarySummary()
            pb.ParseFromString(raw)
            return cls(pb.flights, pb.price.price, pb.price.currency)
        except Exception:
            return cls("", 0, "")  # empty currency = unknown (Itinerary.currency returns None)
